WITH "r0" AS ( SELECT "s".* FROM "public"."article" AS "s" WHERE true AND ( ( true ) ) ORDER BY "s"."id" ASC NULLS LAST LIMIT 2 ) SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT 'article' AS "__typename" , "t0"."id" AS "id" , "c2"."j" AS "author" , coalesce( "c3"."j" , '[]'::json ) AS "comments" ) AS "%")) ORDER BY "t0"."id" ASC NULLS LAST ), '[]') FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT 'author' AS "kind" , "t1"."name" AS "name" ) AS "%")) AS "j" FROM ( SELECT "s".* FROM "public"."author" AS "s" WHERE true AND "s"."id" = "t0"."author_id" AND ( ( true ) ) LIMIT 1 ) AS "t1" ) AS "c2" ON true LEFT JOIN (WITH "r1" AS ( SELECT "s".* FROM "public"."comment" AS "s" WHERE ( "s"."article_id" ) IN (SELECT "id" FROM "r0" ) AND ( ( true ) ) ) SELECT "t1"."article_id" AS "k0" , coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT 'comment' AS "__typename" , "t1"."id" AS "id" ) AS "%")) ), '[]') AS "j" FROM "r1" AS "t1" GROUP BY "t1"."article_id" ) AS "c3" ON true AND "c3"."k0" = "t0"."id"
